"""Original multilayer SVG office. No raster, downloads, text or external resources."""
from pathlib import Path
from random import Random
root=Path(__file__).resolve().parents[1]
out=root/'public'/'assets'
rng=Random(606)
def save(name,body,defs=''):
 (out/name).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1000"><defs>{defs}</defs>{body}</svg>',encoding='utf-8')
# Distant office: bookcase with individually drawn file spines, panelling and a night window.
room_defs='''<linearGradient id="wall" x2="0" y2="1"><stop stop-color="#07100e"/><stop offset="1" stop-color="#17231d"/></linearGradient><linearGradient id="wood" x2="1" y2="0"><stop stop-color="#111a13"/><stop offset=".45" stop-color="#2b3021"/><stop offset=".6" stop-color="#17231a"/><stop offset="1" stop-color="#080f0b"/></linearGradient><linearGradient id="night" x2="0" y2="1"><stop stop-color="#081720"/><stop offset="1" stop-color="#172b2a"/></linearGradient><filter id="distance"><feGaussianBlur stdDeviation="1.8"/></filter><radialGradient id="haze"><stop stop-color="#78927c" stop-opacity=".13"/><stop offset="1" stop-color="#405c4c" stop-opacity="0"/></radialGradient>'''
files=[]
for shelf,y in enumerate([95,260,425]):
 x=77
 for j in range(23):
  w=rng.randrange(11,25);h=rng.randrange(92,143);tone=rng.choice(['#26352a','#344031','#243429','#384433','#202f26'])
  files.append(f'<g transform="translate({x} {y+145-h}) rotate({rng.choice([-3,0,0,1,2])})"><path d="M0 0h{w}v{h}H0Z" fill="{tone}" stroke="#4b5140" stroke-opacity=".2"/><path d="M3 7v{h-14}M5 12h{w-10}M5 {h-15}h{w-10}" stroke="#6c7154" stroke-width=".7" opacity=".25"/><rect x="4" y="28" width="{w-8}" height="27" fill="#959178" opacity=".12"/></g>');x+=w+3
city=[]
for x in range(1100,1580,31):
 y=rng.randrange(245,340);h=410-y
 city.append(f'<path d="M{x} {y}h27v{h}h-27Z" fill="#0a1718"/>')
 for yy in range(y+12,400,17):
  if rng.random()<.45:city.append(f'<path d="M{x+6} {yy}h3m10 0h3" stroke="#9aab8e" stroke-width="2" opacity="{rng.choice([.15,.2,.28])}"/>')
room='''<rect width="1600" height="1000" fill="url(#wall)"/><g filter="url(#distance)"><path d="M30 20h800v616H30Z" fill="url(#wood)"/><path d="M48 38h765v561H48Z" fill="#08100b"/>'''+''.join(files)+'''<path d="M38 79h784M38 246h784M38 411h784M38 577h784" stroke="#3b3f2b" stroke-width="12"/><path d="M43 254h773M43 419h773M43 585h773" stroke="#080f0b" stroke-width="5"/><path d="M57 25v597M805 25v597" stroke="#3d412d" stroke-width="16"/><path d="M850 28h5v559h-5Z" fill="#343c2e"/><path d="M888 0h15v600h-15Z" fill="#0a120e"/><path d="M1090 30h495v421h-495Z" fill="#060d0c"/><path d="M1105 44h464v389h-464Z" fill="url(#night)"/>'''+''.join(city)+'''<path d="M1104 432h470M1336 46v388M1105 225h465" stroke="#090f0d" stroke-width="13"/><path d="M1345 47v381M1107 232h460" stroke="#3b4b40" stroke-width="1" opacity=".5"/><path d="M1081 441h515v17h-515Z" fill="url(#wood)"/><path d="M1030 0h37v535h-37Z" fill="#121f17"/></g><ellipse cx="1270" cy="320" rx="480" ry="340" fill="url(#haze)"/>'''
save('scene-room.svg',room,room_defs)
# Midground: green baize desk with solid wood bevel and non-repeating grain.
desk_defs='''<linearGradient id="felt" x1=".2" y1="0" x2=".8" y2="1"><stop stop-color="#253e2d"/><stop offset=".45" stop-color="#183123"/><stop offset="1" stop-color="#07170f"/></linearGradient><linearGradient id="edge" x2="0" y2="1"><stop stop-color="#343727"/><stop offset=".2" stop-color="#4b4931"/><stop offset=".35" stop-color="#1c271a"/><stop offset="1" stop-color="#070e09"/></linearGradient><pattern id="baize" width="7" height="7" patternUnits="userSpaceOnUse"><path d="M0 0 7 7M0 7 7 0" stroke="#758674" stroke-width=".4" opacity=".12"/></pattern><linearGradient id="desk-depth" x2="0" y2="1"><stop stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".45"/></linearGradient>'''
grain=''.join(f'<path d="M-20 {y}Q{rng.randrange(300,700)} {y+rng.randrange(-20,20)} 1630 {y+rng.randrange(-8,8)}" stroke="#797353" stroke-width="{rng.choice([.35,.5,.7])}" opacity="{rng.choice([.03,.04,.07])}" fill="none"/>' for y in range(525,995,8))
desk='''<path d="M0 575 1600 445V1000H0Z" fill="#070e09"/><path d="M0 591 1600 459v471L0 1040Z" fill="url(#edge)"/><path d="M0 581 1599 454v440L0 1000Z" fill="url(#felt)"/><path d="M0 581 1599 454v440L0 1000Z" fill="url(#baize)"/><path d="M0 581 1599 454M0 596 1599 467" stroke="#74816a" stroke-opacity=".2" stroke-width="1.2"/><path d="M0 997 1600 890" stroke="#797457" stroke-opacity=".23" stroke-width="2"/>'''+grain+'''<path d="M0 581 1599 454v440L0 1000Z" fill="url(#desk-depth)"/>'''
save('scene-desk.svg',desk,desk_defs)
# A sculpted green glass banker lamp: curved shade, enamel reflections, metal fittings, pull chain.
lamp_defs='''<linearGradient id="glass" x1=".05" y1="0" x2=".9" y2="1"><stop stop-color="#071c12"/><stop offset=".23" stop-color="#2f6941"/><stop offset=".36" stop-color="#4e8155"/><stop offset=".48" stop-color="#244e31"/><stop offset=".85" stop-color="#0b2c1a"/><stop offset="1" stop-color="#07170e"/></linearGradient><linearGradient id="glass-top" x2="0" y2="1"><stop stop-color="#578361" stop-opacity=".65"/><stop offset="1" stop-color="#183d25" stop-opacity="0"/></linearGradient><linearGradient id="steel" x2="1" y2="0"><stop stop-color="#293327"/><stop offset=".22" stop-color="#8e9275"/><stop offset=".4" stop-color="#d3c69b"/><stop offset=".5" stop-color="#555d47"/><stop offset=".76" stop-color="#9b9c7a"/><stop offset="1" stop-color="#202f23"/></linearGradient><linearGradient id="under" x2="0" y2="1"><stop stop-color="#d9c591"/><stop offset=".6" stop-color="#a69b73"/><stop offset="1" stop-color="#4b6143"/></linearGradient><radialGradient id="lamp-shadow"><stop stop-color="#020805" stop-opacity=".85"/><stop offset="1" stop-color="#020805" stop-opacity="0"/></radialGradient>'''
chain=''.join(f'<circle cx="1329" cy="{y}" r="1.4" fill="#a8aa84"/>' for y in range(253,376,5))
lamp='''<ellipse cx="1374" cy="694" rx="188" ry="53" fill="url(#lamp-shadow)"/><path d="M1360 333 1431 691 1265 700 1298 336Z" fill="#020805" opacity=".18"/><g><ellipse cx="1374" cy="654" rx="102" ry="18" fill="#07130c"/><path d="M1278 647q9-31 96-31t96 31q-4 19-96 21t-96-21" fill="url(#steel)"/><ellipse cx="1374" cy="644" rx="83" ry="13" fill="#283c28"/><ellipse cx="1374" cy="640" rx="74" ry="10" fill="#3a4c31"/><path d="M1296 644q78 12 156-1" stroke="#a7a581" opacity=".35" fill="none"/><path d="M1368 624V386q0-49-26-79l-26-33 11-8 28 36q28 33 28 82v240" fill="url(#steel)"/><path d="M1370 612V389q0-50-26-80l-25-30" stroke="#c3bb94" stroke-width="1.5" opacity=".6" fill="none"/><path d="M1362 612h25v11h-25zM1364 598h22v6h-22z" fill="url(#steel)"/><circle cx="1350" cy="317" r="12" fill="url(#steel)"/><circle cx="1350" cy="317" r="6" fill="#46543c"/><path d="M1261 267q-26-2-34-18t1-41M1428 219q17 9 13 28t-28 24" stroke="url(#steel)" stroke-width="8" fill="none"/><path d="M1190 190q6-70 75-89 72-18 140 25l45 80q-97 55-260-16" fill="url(#glass)" stroke="#56805a" stroke-opacity=".35" stroke-width="1.4"/><path d="M1204 170q26-62 77-62t105 28l19 34q-82-30-201 0" fill="url(#glass-top)"/><path d="M1228 141q53-46 118-15" fill="none" stroke="#8baf85" opacity=".3" stroke-width="2"/><path d="M1243 128q35-18 68-8" fill="none" stroke="#c2ceb1" opacity=".32" stroke-width="1"/><path d="M1190 190q139-13 260 16-18 59-137 40t-123-56" fill="#15311f" stroke="#718264" stroke-opacity=".7" stroke-width="2"/><ellipse cx="1320" cy="214" rx="126" ry="22" transform="rotate(5 1320 214)" fill="url(#under)"/><path d="M1200 197q128-10 242 16" stroke="#cfc6a5" stroke-width="1.2" opacity=".6" fill="none"/><path d="M1244 214q78-1 138 7" stroke="#ede2bc" opacity=".65" stroke-width="5" stroke-linecap="round"/>'''+chain+'''<ellipse cx="1329" cy="380" rx="4" ry="7" fill="url(#steel)"/><path d="M1404 151q18 20 26 43" stroke="#091e11" stroke-width="7" fill="none" opacity=".45"/></g>'''
save('scene-lamp.svg',lamp,lamp_defs)
light_defs='''<linearGradient id="beam" x1=".8" y1="0" x2=".3" y2="1"><stop stop-color="#e6cf99" stop-opacity=".28"/><stop offset=".3" stop-color="#c6b47e" stop-opacity=".13"/><stop offset="1" stop-color="#b7ad7b" stop-opacity="0"/></linearGradient><radialGradient id="pool"><stop stop-color="#d8cb9c" stop-opacity=".24"/><stop offset=".5" stop-color="#c1b880" stop-opacity=".1"/><stop offset="1" stop-color="#c4bc8e" stop-opacity="0"/></radialGradient><filter id="soft-beam"><feGaussianBlur stdDeviation="16"/></filter>'''
light='''<path d="M1196 215 1436 239 1599 870 465 973Z" fill="url(#beam)" filter="url(#soft-beam)"/><path d="M1212 222 1431 238 1580 885 535 974Z" fill="url(#beam)" opacity=".45"/><ellipse cx="1090" cy="790" rx="510" ry="245" transform="rotate(-7 1090 790)" fill="url(#pool)"/>'''
save('scene-light.svg',light,light_defs)
# Three pieces of evidence on the desk: a fountain pen, stamp pad and worn file stack.
props_defs='''<linearGradient id="pen" x2="0" y2="1"><stop stop-color="#5a6351"/><stop offset=".22" stop-color="#171f17"/><stop offset=".5" stop-color="#394735"/><stop offset=".75" stop-color="#101c13"/><stop offset="1" stop-color="#060c08"/></linearGradient><linearGradient id="pad" x2="0" y2="1"><stop stop-color="#475241"/><stop offset="1" stop-color="#111d13"/></linearGradient><radialGradient id="contact"><stop stop-color="#000" stop-opacity=".8"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient>'''
props='''<g transform="translate(1220 750) rotate(-9)"><ellipse cx="145" cy="60" rx="174" ry="60" fill="url(#contact)"/><path d="M0 10 259 5 275 79 10 93Z" fill="#38432d" stroke="#687054" stroke-width="1"/><path d="M8 0 255 0 266 72 15 86Z" fill="#5e6950"/><path d="m5 13 255-8m-252 18 254-8m-251 18 254-8" stroke="#9a9c78" opacity=".35"/><path d="M12-12h91l14 12h144l8 66L19 80Z" fill="#334a33" stroke="#6a7657"/><path d="M26 6h215M31 65l216-13" stroke="#70805f" opacity=".4"/></g><g transform="translate(1260 871) rotate(-10)"><ellipse cx="100" cy="55" rx="135" ry="38" fill="url(#contact)"/><rect width="180" height="73" rx="9" fill="url(#pad)" stroke="#6a745b"/><rect x="9" y="9" width="162" height="55" rx="5" fill="#08160e"/><rect x="17" y="15" width="147" height="42" rx="4" fill="#183326"/><path d="M23 20h132M23 24h132M23 29h132M23 34h132M23 39h132M23 44h132M23 49h132" stroke="#3b4c3b" stroke-width=".45" opacity=".6"/><path d="M63-7h57v8H63Z" fill="#7d8162"/></g><g transform="translate(732 906) rotate(-14)"><ellipse cx="159" cy="15" rx="190" ry="28" fill="url(#contact)"/><path d="M12 1h241q25 0 25 11t-25 10H12Z" fill="url(#pen)" stroke="#55644b" stroke-width=".8"/><path d="m12 1-34 11 34 10" fill="#9c9a71"/><path d="m-18 12 30-1" stroke="#333e29" stroke-width="1"/><path d="M71 1v21M77 1v21" stroke="#a4a27b" stroke-width="2"/><path d="M171 1h64q8 0 8 5l-5 1h-65" stroke="#9e9f7b" stroke-width="2" fill="none"/><path d="M89 6h67" stroke="#9eab87" stroke-opacity=".45" stroke-width="1"/></g>'''
save('scene-props.svg',props,props_defs)
print('Created five original office layers:',sum((out/n).stat().st_size for n in ['scene-room.svg','scene-desk.svg','scene-lamp.svg','scene-light.svg','scene-props.svg']),'bytes')
